/**
 * Spatial hashing grid to accelerate neighbor queries for particle simulations.
 *
 * Responsibilities:
 * - Compute cell hash for each particle, sort by hash, and build cell offsets.
 * - Provide helper functions to map positions to cell coordinates and hash keys.
 *
 * Sorting Algorithms:
 * - 'bitonic' (default): Uses ComputeBitonicSort - O(n log²n), works on WebGPU and WebGL.
 * - 'radix': Uses ComputeRadixSort - O(n) complexity, WebGPU only.
 *
 * Usage:
 * - Call `setInput(positions, particleCount)` to set the input buffer and allocate internal buffers.
 * - Call `computeGrid(renderer)` every frame before neighbor-dependent compute passes.
 *
 * @class SpatialGrid
 * @category Simulation
 * @tags WebGPU
 * @private
 * @example
 * import { SpatialGrid } from '@three-blocks/core';
 * import { instancedArray } from 'three/tsl';
 * import * as THREE from 'three/webgpu';
 *
 * // Create particle positions buffer
 * const particleCount = 4096;
 * const positions = new Float32Array(particleCount * 3);
 * for (let i = 0; i < particleCount; i++) {
 *   positions[i * 3] = Math.random() * 20 - 10;
 *   positions[i * 3 + 1] = Math.random() * 20 - 10;
 *   positions[i * 3 + 2] = Math.random() * 20 - 10;
 * }
 * const positionsBuffer = instancedArray(positions, 'vec3').setPBO(true);
 *
 * // Create spatial grid (default: bitonic sort)
 * const grid = new SpatialGrid({
 *   is3D: true,
 *   kernelRadius: 1.0,
 *   domainDimensions: new THREE.Vector3(20, 20, 20),
 *   sortAlgorithm: 'bitonic' // or 'radix' for WebGPU-only O(n) sorting
 * });
 *
 * // Initialize grid with positions
 * grid.setInput(positionsBuffer, particleCount);
 *
 * // In your render loop
 * function animate() {
 *   // Update grid before neighbor queries
 *   grid.computeGrid(renderer);
 *
 *   // Use grid data in your compute shaders
 *   // grid.buffers.cellHashes - sorted cell hashes
 *   // grid.buffers.particleIds - sorted particle indices (parallel to cellHashes)
 *   // grid.buffers.cell_offsets - cell offset lookup table
 *   // grid.ubos.grid_cell_size - uniform cell dimensions
 *   // grid.ubos.grid_resolution - grid resolution
 *
 *   renderer.render(scene, camera);
 *   requestAnimationFrame(animate);
 * }
 *
 * // Clean up
 * grid.dispose();
 */
export class SpatialGrid {
    /**
   * Grid-only structure to accelerate neighbor queries.
   * - Call setInput(positions, particleMaxCount) once (or when particle count changes)
   * - Call computeGrid(renderer) every frame *before* your neighbor-dependent compute passes.
   * @param {Object} options - Configuration options.
   * @param {boolean} [options.is3D=false] - Whether to use 3D spatial grid.
   * @param {number} [options.kernelRadius=1.0] - Kernel radius for neighbor queries.
   * @param {THREE.Vector3} [options.domainDimensions] - Domain dimensions.
   * @param {boolean} [options.debug=false] - Enable debug mode.
   * @param {'bitonic'|'radix'} [options.sortAlgorithm='bitonic'] - Sorting algorithm to use.
   *   'bitonic' uses ComputeBitonicSort (WebGPU + WebGL compatible).
   *   'radix' uses ComputeRadixSort (WebGPU only, O(n) complexity).
   */
    constructor({ is3D, kernelRadius, domainDimensions, debug, sortAlgorithm }?: {
        is3D?: boolean;
        kernelRadius?: number;
        domainDimensions?: THREE.Vector3;
        debug?: boolean;
        sortAlgorithm?: "bitonic" | "radix";
    });
    is3D: boolean;
    /**
     * Sorting algorithm: 'bitonic' or 'radix'
     * @type {string}
     */
    sortAlgorithm: string;
    /**
 * Whether to enable debug mode.
 * @type {boolean}
 */
    debug: boolean;
    gridCellSize: any;
    gridResolution: any;
    gridCellCount: number;
    _domainMatrix: any;
    ubos: {
        grid_cell_size: any;
        grid_resolution: any;
        count_cells: any;
        domainDimensions: any;
        domainMatrix: any;
        kernel_radius: any;
        particleCount: any;
        max_particles: any;
    };
    inputPositions: any;
    particleMaxCount: number;
    workgroupSize: number;
    workgroupSizeVec: number[];
    workGroupsCount: number[];
    buffers: {
        cellHashes: any;
        particleIds: any;
        cell_offsets: any;
        sortData: any;
    };
    cellOffsetsCapacity: number;
    sorter: ComputeBitonicSort | ComputeRadixSort;
    splitCompute: any;
    /**
   * Update kernel radius and/or domain dimensions, recomputing grid cell size,
   * resolution, and internal buffers. Rebuilds compute passes to update dispatch sizes.
   * @param {number} newKernelRadius
   * @param {THREE.Vector3} [newDomainDimensions]
   * @returns {boolean} true if buffers were reallocated (requires rebuild of dependent passes)
   */
    updateKernelRadius(newKernelRadius: number, newDomainDimensions?: THREE.Vector3): boolean;
    /**
     * Set the input positions buffer and particle count. Allocates grid buffers and initializes sorter.
     * @param {any} positions - Instanced array node or storage representing positions (vec3 per particle).
     * @param {number} particleCount - Active particle count.
     */
    setInput(positions: any, particleCount: number): void;
    _buildHelpers(): void;
    positionToCellCoords: any;
    cellKeyToHash: any;
    _buildCompute(): void;
    clearOffsets: any;
    computeIndices: any;
    computeOffsets: any;
    /**
   * Build/update the grid for current positions: compute indices, sort by cell key, and compute cell offsets.
   * Should be called before any neighbor-dependent compute pass each frame.
   * @param {THREE.WebGPURenderer} renderer
   */
    computeGrid(renderer: THREE.WebGPURenderer): void;
    dispose(): void;
}
import { ComputeBitonicSort } from '../../Compute/ComputeBitonicSort.js';
import { ComputeRadixSort } from '../../Compute/ComputeRadixSort.js';
